//! FillBase.cpp:2712-2784: shared multiline offset union consumer controls.
//! Native references are generated by slice_case; only authored meshes are tracked.
use super::*;
use serde_json::json;

#[path = "multiline_union_observation.rs"]
pub(crate) mod observation;

const FIXED: [(&str, &str); 22] = [
    ("layer_height", "0.2"),
    ("initial_layer_print_height", "0.2"),
    ("wall_generator", "classic"),
    ("wall_loops", "2"),
    ("bottom_surface_pattern", "rectilinear"),
    ("top_surface_pattern", "rectilinear"),
    ("internal_solid_infill_pattern", "rectilinear"),
    ("bottom_shell_layers", "3"),
    ("top_shell_layers", "3"),
    ("enable_support", "0"),
    ("raft_layers", "0"),
    ("brim_type", "no_brim"),
    ("skirt_loops", "0"),
    ("enable_prime_tower", "0"),
    ("enable_arc_fitting", "0"),
    ("spiral_mode", "0"),
    ("seam_slope_type", "none"),
    ("fuzzy_skin", "none"),
    ("small_area_infill_flow_compensation", "0"),
    ("xy_contour_compensation", "0"),
    ("xy_hole_compensation", "0"),
    ("elefant_foot_compensation", "0"),
];

fn compare(label: &str, pattern: &str, count: &str, hole: bool) {
    let Some(runner) = OrcaRunner::from_env().unwrap() else {
        return;
    };
    let root = parity::artifacts::root_from_env().unwrap();
    let profiles = VendorProfiles::load(&profiles_root(), "Creality").unwrap();
    let selection =
        parity::select_printer(&profiles, "Creality", "Creality Ender-3 0.4 nozzle").unwrap();
    let machine = profiles.machine(&selection.printer).unwrap();
    let mut process = profiles.process(&selection.process).unwrap();
    parity::normalize_process_defaults(&machine, &mut process);
    let mut filaments = selection
        .filaments
        .iter()
        .map(|name| profiles.filament(name).unwrap())
        .collect::<Vec<_>>();
    parity::normalize_filament_defaults(&mut filaments);
    for (key, value) in FIXED {
        process.insert(key.into(), json!(value));
    }
    let density = "30%";
    let angle = "45";
    let variable = [
        ("sparse_infill_pattern", pattern),
        ("fill_multiline", count),
        ("sparse_infill_density", density),
        ("infill_direction", angle),
    ];
    for (key, value) in variable {
        process.insert(key.into(), json!(value));
    }
    let mesh = if hole { "holed-prism" } else { "prism" };
    let label = format!("multiline-union/{label}");
    let exported = runner
        .export_case(
            &runner::CaseInputs {
                label: &label,
                machine: &machine,
                process: &process,
                filaments: &filaments,
            },
            &parity::smoke_overrides(),
            &runner::repo_root().join(format!("tests/parity/multiline-union/{mesh}.stl")),
        )
        .unwrap();
    for (key, value) in FIXED.into_iter().chain(variable) {
        runner::application::verify_value(&exported.project, key, &json!(value)).unwrap();
    }
    let sliced = runner.slice_case(&exported).unwrap();
    let native = observation::observe(&sliced.reference);
    let outcome = parity::compare_case(&sliced);
    let artifact = outcome.artifacts.as_ref().unwrap();
    let ares = if outcome.status == "ARES_ERROR" {
        None
    } else {
        Some(observation::observe(
            &std::fs::read(artifact.join("ares.gcode")).unwrap(),
        ))
    };
    parity::artifacts::overwrite(
        &root.join(format!("{}.json", label.replace('/', "-"))),
        &serde_json::to_vec_pretty(&json!({
            "label":label,"pattern":pattern,"count":count,"density":density,"angle":angle,
            "hole":hole,
            "native":native,"ares":ares,"status":outcome.status,
            "detail":outcome.detail,"artifacts":artifact,
        }))
        .unwrap(),
    )
    .unwrap();
    observation::require_sparse(&native);
    if let Some(ares) = &ares {
        observation::require_sparse(ares);
    }
    if hole {
        observation::require_hole_clipping(&native);
    }
    assert_eq!(
        outcome.status, "PASS",
        "{}: {} ({artifact:?})",
        label, outcome.detail
    );
}

#[test]
fn orca_parity_multiline_union_r1() {
    compare("R1", "rectilinear", "1", false);
}

#[test]
fn orca_parity_multiline_union_g1() {
    compare("G1", "grid", "1", false);
}

#[test]
fn orca_parity_multiline_union_c1() {
    compare("C1", "cubic", "1", false);
}

#[test]
fn orca_parity_multiline_union_c2() {
    compare("C2", "cubic", "2", false);
}

#[test]
fn orca_parity_multiline_union_c3() {
    compare("C3", "cubic", "3", false);
}

#[test]
fn orca_parity_multiline_union_h1() {
    compare("H1", "honeycomb", "1", false);
}

#[test]
fn orca_parity_multiline_union_h2() {
    compare("H2", "honeycomb", "2", false);
}

#[test]
fn orca_parity_multiline_union_h3() {
    compare("H3", "honeycomb", "3", false);
}

#[test]
fn orca_parity_multiline_union_hc2() {
    compare("HC2", "cubic", "2", true);
}

#[test]
fn orca_parity_multiline_union_hh2() {
    compare("HH2", "honeycomb", "2", true);
}
